CREATE TABLE dbo.Users (
    UserId INT IDENTITY CONSTRAINT PK_Users PRIMARY KEY,
    LoginName NVARCHAR(100) NOT NULL CONSTRAINT UQ_Users_Login UNIQUE,
    NationalId CHAR(13) NULL
);
-- Many NULL NationalIds allowed, non-NULLs unique:
CREATE UNIQUE INDEX UX_Users_NationalId ON dbo.Users(NationalId)
    WHERE NationalId IS NOT NULL;

CREATE SEQUENCE dbo.DocumentNumber
    AS INT
    START WITH 10000
    INCREMENT BY 1
    CACHE 100;

-- Same series across two tables:
CREATE TABLE dbo.Invoices   (DocNo INT DEFAULT (NEXT VALUE FOR dbo.DocumentNumber) PRIMARY KEY, ...);
CREATE TABLE dbo.CreditNotes(DocNo INT DEFAULT (NEXT VALUE FOR dbo.DocumentNumber) PRIMARY KEY, ...);
